<template><div><PageHeader title="Attendance" description="Record session attendance and keep learner progress accurate."><template #actions><button class="btn secondary" @click="push('Attendance saved for this session.')">Save attendance</button></template></PageHeader><div class="card"><div class="form-section"><div class="form-grid"><div class="field"><label>Course</label><select class="select"><option>Laravel Fundamentals</option><option>Python for APIs</option></select></div><div class="field"><label>Batch</label><select class="select"><option>2026-09-A</option><option>2026-09-B</option></select></div><div class="field"><label>Session</label><select class="select"><option>Session 06 · 18 Sep 2026</option><option>Session 07 · 20 Sep 2026</option></select></div><div class="field"><label>Date</label><input class="input" type="date" value="2026-09-18"></div></div></div><div class="toolbar"><div class="toolbar-left"><button class="btn secondary small" @click="markAll('present')">Mark all present</button><button class="btn secondary small" @click="markAll('absent')">Mark all absent</button></div><span class="section-note">32 learners · 29 present</span></div><DataTable :headers="['Learner','Status','Notes']"><tr v-for="row in rows" :key="row.id"><td><div class="row-person"><Avatar :name="row.name" size="sm"/><strong>{{row.name}}</strong></div></td><td><select class="select" style="width:130px" v-model="row.status"><option>present</option><option>absent</option><option>late</option><option>excused</option></select></td><td><input class="input" placeholder="Optional note" v-model="row.note"></td></tr></DataTable></div></div></template>
<script setup lang="ts">import {ref} from 'vue';import PageHeader from '../components/PageHeader.vue';import DataTable from '../components/DataTable.vue';import Avatar from '../components/Avatar.vue';import {learners} from '../data/mock';import {useToast} from '../composables/useToast';const {push}=useToast();const rows=ref(learners.map(l=>({id:l.id,name:l.name,status:'present',note:''})));function markAll(status:string){rows.value.forEach(r=>r.status=status);push(`All learners marked ${status}.`,'info')}</script>
